              id="profile-name"
              value={settings.name}
              onChange={(event) =>
                setSettings((current) => ({ ...current, name: event.target.value }))
              }
            />
          </Field>

          <Field label="Язык интерфейса" htmlFor="profile-language">
            <Select
              id="profile-language"
              value={settings.language}
              options={LANGUAGE_OPTIONS}
              onChange={(value: ProfileSettings['language']) =>
                setSettings((current) => ({ ...current, language: value }))
              }
            />
          </Field>

          <Switch
            id="profile-email-notifications"
            label="Уведомления на почту"
            checked={settings.emailNotifications}
